"use strict";

window.addEventListener("load", myMain, false);

function myMain(evt) {
  // DO YOUR STUFF HERE.

  // window.scrollBy(0, 800);
  var delayInMilliseconds = 1200; //1 second

  setTimeout(function () {
    //your code to be executed after 1 second

    chrome.runtime.sendMessage(
      {
        type: "url_visited",
        payload: {
          message: window.location.href,
        },
      },
      (response) => {
        console.log(response);
        if (response.length > 3) {
          window.scrollBy(0, 1000);
        }

        setTimeout(function () {
          //your code to be executed after 1 second

          // console.log(response);
          //add a delay timer to load up elements initially.

          if (response.length > 3) {
            //now grab the xpath/s
            //   console.log(getElementByXpath(response));

            var xpathArray = [];

            if (response.includes(",")) {
              xpathArray = response.toString().split(",");
            } else {
              xpathArray.push(response.toString());
            }

            // console.log(xpathArray);
            // console.log("xpath arra above");

            var outPut = [];

            for (var i = 0; i < xpathArray.length; i++) {
              if (xpathArray[i].includes("$")) {
                //gotta repeat

                var j = 0;
                var flag = false;
                while (1) {
                  console.log(xpathArray[i]);
                  var res = getElementByXpath(
                    xpathArray[i].replace("$", j.toString())
                  );
                  //   console.log(res.textContent);

                  if (flag === true && res === null) {
                    break;
                  }

                  if (res != null) {
                    if (xpathArray[i].substring(0, 3) === "URL") {
                      outPut.push(res.getAttribute("href"));
                    } else {
                      outPut.push(res.textContent);
                    }
                    flag = true;
                  }

                  if (j > 13 && res === null) {
                    break;
                  }

                  j++;
                }

                // chrome.runtime.sendMessage({
                //   type: "scrapedData",
                //   payload: {
                //     data: outPut,
                //     message: window.location.href,
                //   },
                // });
              } else {
                var res2 = getElementByXpath(xpathArray[i]);
                // chrome.runtime.sendMessage({
                //   type: "scrapedDataSingle",
                //   payload: {
                //     data: res2.textContent,
                //     message: window.location.href,
                //   },
                // });
                if (xpathArray[i].substring(0, 3) === "URL") {
                  outPut.push(res2.getAttribute("href"));
                } else {
                  outPut.push(res2.textContent);
                }
              }
            }
            // console.log(outPut);
            chrome.runtime.sendMessage({
              type: "scrapedData",
              payload: {
                data: outPut,
                message: window.location.href,
              },
            });

            return true;
          }
        }, 1200);
        //delayer
      }
    );
  }, delayInMilliseconds);

  //helper functions
  function getElementByXpath(path) {
    try {
      if (path.substring(0, 3) === "URL") {
        path = path.substring(3, path.length);
      }
      let res = document.evaluate(
        path,
        document,
        null,
        XPathResult.FIRST_ORDERED_NODE_TYPE,
        null
      ).singleNodeValue;

      // if (path.substring(0, 3) === "URL") {
      //   return res.getAttribute("href");
      // }

      return res;
    } catch (e) {
      console.log(e);
      return null;
    }
  }
}
